ret.x = GetPixel(uv_bg).x - (GetPixel(uv_bg).x - GetBlur3(uv_bg).x)*0.02 - 0.008;
ret.y = texture( sampler_main, uv_y ).y;
ret.y += (ret.y - GetBlur1(uv).y)*0.2 - 0.004;
vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw + rand_frame.xy;
uv_bg = uv_orig -(uv_orig-uv) * 2.0 + (texture(sampler_noise_lq, dither_uv).xyz-0.5)*(vec2(1.0)/uTexSize);
ret.z = GetPixel(uv_bg).z - 0.004;
}

